function selfFunction()
	self.setColorTint({r=1,b=1,g=1})
	self.setLock(false)
	self.flip()
	Wait.condition(function() self.lock() end, function() return self.resting end, 10)
end

function unlockChest(_, _, rightclick)
  if not rightclick then return end

  pos = self.getPosition()
  name = "S 125"
  infChestBag = getObjectFromGUID("fe14ef")
  local ChestBag = infChestBag.takeObject({
  position = {-142.78, -2.00, 13.09},
  smooth = true
  })
  for _, obj in pairs(ChestBag.getObjects()) do
    if obj.name == name then
      ChestBag.takeObject({
      position = {pos[1], pos[2] + 1, pos[3]},
      rotation = {0.00, 180.00, 0.00},
      smooth = false,
      callback_function = function(obj) obj.setPositionSmooth({pos[1], pos[2] + 1, pos[3]}) obj.setRotationSmooth({0.00, 180.00, 0.00}) end,
      guid = obj.guid
      })

    end
  end
  ChestBag.destruct()
self.clearButtons()
end

