    if j.name == deck then
      local infiDeck = backupChest.takeObject({
        position       = {-95, 2, 0},
        smooth         = false,
        guid           = j.guid
      })
      if deck == "Player Reference" then
        local modDeck = infiDeck.clone({
          position     = decks[deck].pos
        })
        Timer.create({
          identifier     = "modDeck",
          function_name  = "rotateDeck",
          function_owner = self,
          parameters     = {modDeck},
          delay          = 0.1
        })
      else
        infiDeck.takeObject({position = decks[deck].pos, rotation = decks[deck].rot, smooth = false})
