local TableUtil = require("sebaestschjin-tts.TableUtil")
local Logger = require("sebaestschjin-tts.Logger")

local ClassInfo = {}

local Names = {
    AttackModifierCard = "Attack Modifier",
}

local FoundAbility = {
    None = 0,
    Exact = 1,
    Nearest = 2,
    Extra = 3,
}

function registerCustomClass(params)
  if not params.name then
      Logger.error("Name must be provided")
      return
  end
  if not params.info then
      Logger.error("Details not provided for custom class '%s'", name)
      return
  end

  if ClassInfo.Classes[params.name] then
    -- not sure about this. loading enhancement reloads, so might be annoying
    -- Logger.error("A class with the name '%s' has already been registered", name)
    return
  end
  params.info.isSpecialClass = true
  ClassInfo.Classes[params.name] = params.info
end

function getClass(params)
    return class(params.className)
end

function class(name)
    local classInfo = ClassInfo.Classes[name]
    if not classInfo then
        Logger.warn("Tried to get class information for class '%s', but it doesn't exist!", name)
    end
    return classInfo
end

function getAbilityForUnknownClass(params)
  local name = Object.name(params.card)
  if not Object.isCard(params.card)
          or name:find(Names.AttackModifierCard)
  then
      return nil
  end

  local cardName = StringUtil.replace(name, "%s?[%(%)]%d%d[%)%(]")

  local exactCard
  for className,_ in pairs(ClassInfo.Classes) do
    local ability, state = exactAbility(className, cardName)

    if state == FoundAbility.Exact then
      return className, ability
    end
  end
end

function ability(className, abilityName)
    local ability, state = nearestAbility(className, abilityName)

    if state == FoundAbility.Extra then
        Logger.debug("Found extra card '%s' for class '%s'", abilityName, className)
    elseif state == FoundAbility.Nearest then
        Logger.warn("Tried to get ability information for '%s' of class '%s', but it doesn't exist."
                .. " However, found the ability '%s' which is similar in name which will be used instead."
                .. " Maybe there's a typo in the ability name."
                .. " Please verify that this assumption is correct.",
                abilityName, className, (--[[---@not nil]] ability).name)
    elseif state == FoundAbility.None then
        local classInfo = class(className)
        if classInfo then
          local allNames = TableUtil.keys(classInfo.abilities)
          Logger.error("Tried to get ability information for '%s' of class '%s', but it doesn't exist!"
                  .. " Also couldn't find any ability that is similar. Avaible abilities are: [%s].",
                  abilityName, className, table.concat(allNames, ", "))
        end
        ability = abilityName
    end

    return ability
end

function exactAbility(className, abilityName)
    local classInfo = class(className)
    local state = FoundAbility.None
    if classInfo then
        if isExtraCard(className, abilityName) then
          return nil, FoundAbility.Extra
        end

        local abilityInfo = classInfo.abilities[abilityName]
        if abilityInfo then
            abilityInfo.name = abilityName
            state = FoundAbility.Exact
        end

        return abilityInfo, state
    end
    return nil, state
end

function nearestAbility(className, abilityName)
    local classInfo = class(className)
    local state = FoundAbility.None
    if classInfo then
        if isExtraCard(className, abilityName) then
          return nil, FoundAbility.Extra
        end

        local abilityInfo = classInfo.abilities[abilityName]
        if not abilityInfo then
            local allNames = TableUtil.keys(classInfo.abilities)
            local nearestName = StringUtil.findNearest(abilityName, allNames, 3)
            if nearestName then
                abilityInfo = classInfo.abilities[--[[---@not nil]]nearestName]
                abilityInfo.name = nearestName
                state = FoundAbility.Nearest
            end
        else
            abilityInfo.name = abilityName
            state = FoundAbility.Exact
        end

        return abilityInfo, state
    end
    return nil, state
end

function isExtraCard(className, abilityName)
  local classInfo = class(className)
  local state = FoundAbility.None
  if classInfo then
    if classInfo.extra then
        for _, v in pairs(classInfo.extra) do
          if (v.type == "Card" or v.type == "Deck") and v.name == abilityName then
            return true
          end
        end
    end
  end
  return false
end

