function onload()
  self.createButton({
      label= "Bonus Content", click_function="grabCityEvents", function_owner=self,
      position={0.5,1,1.25}, rotation={0,0,0}, height=70, width=450,
      font_size=50, color={0,0,0}, font_color={1,1,1}
  })
end

function grabCityEvents()
  pos = self.getPosition()
  name = "SoX City Events"
  infChests = getObjectFromGUID("fe14ef")
  local ChestBag = infChests.takeObject({
  position = {-142.78, -2, 13.09},
  smooth = true
  })

  for _, obj in pairs(ChestBag.getObjects()) do
    if obj.name == name then
      ChestBag.takeObject({
      position = {pos[1], pos[2] + 1, pos[3]},
      rotation = {0.00, 180.00, 0.00},
      smooth = false,
      callback_function = function(obj) obj.setPositionSmooth({pos[1], pos[2] + 1, pos[3]}) obj.setRotationSmooth({0.00, 180.00, 0.00}) end,
      guid = obj.guid
      })
    end
  end
ChestBag.destruct()
broadcastToAll("You've unlocked the Seeker of Xorn City Event 1! Please add it to your City Events deck. This will give you the chance to unlock additional Seeker of Xorn City Events.", "Green")
self.clearButtons()
end

function onload()
  self.createButton({
      label= self.getName(), click_function="setupScenario", function_owner=self,
      position={0,0.3,1.2}, rotation={0,0,0}, height=250, width=950,
      font_size=100, color={0,0,0}, font_color={1,1,1}
  })
end

function setScenarioPage()
  local FCScenario = getObjectFromGUID('66a664')
  for _,obj in pairs(getAllObjects()) do
  if FCScenario then
  FCScenario.Book.setPage(24)
    end
  end
end

function setupScenario()
  setScenarioPage()
  local params = {}
  params[1] = tonumber(self.getDescription())
  Global.call("createMap", params)
